  // ---- Passport Photo Maker ----
  passportNote: { en: "Use a plain, light background with your face centered and no shadows for the best result. This tool crops and sizes the photo   it does not replace backgrounds   and official acceptance always follows your issuing authority's rules (expression, head covering, glasses and background color requirements vary).", es: 'Usa un fondo liso y claro, con tu rostro centrado y sin sombras para obtener el mejor resultado. Esta herramienta recorta y ajusta el tamaño de la foto (no sustituye fondos), y la aceptación oficial siempre depende de las normas de tu autoridad emisora (la expresión, el velo, las gafas y el color de fondo varían).', fr: "Utilisez un fond uni et clair, le visage centré et sans ombres pour un meilleur résultat. Cet outil recadre et redimensionne la photo   il ne remplace pas les arrière-plans   et l'acceptation officielle dépend toujours des règles de votre autorité de délivrance (l'expression, le couvre-chef, les lunettes et la couleur de fond varient).", ar: 'استخدم خلفية عادية فاتحة مع توسيط وجهك وبدون ظلال للحصول على أفضل نتيجة. تقوم هذه الأداة بقص الصورة وتحديد حجمها   ولا تستبدل الخلفيات   ويتبع القبول الرسمي دائمًا قواعد سلطة الإصدار الخاصة بك (تختلف متطلبات التعبير وغطاء الرأس والنظارات ولون الخلفية).', ru: 'Для лучшего результата используйте однотонный светлый фон, лицо по центру и без теней. Этот инструмент обрезает и масштабирует фото   он не заменяет фоны   а официальное принятие всегда зависит от правил вашего выдающего органа (требования к выражению лица, головному убору, очкам и цвету фона различаются).' },
  couldNotLoadImageFile: { en: 'Could not load that image file.', es: 'No se pudo cargar ese archivo de imagen.', fr: 'Impossible de charger ce fichier image.', ar: 'تعذر تحميل ملف الصورة ذلك.', ru: 'Не удалось загрузить этот файл изображения.' },
  photoSize: { en: 'Photo size', es: 'Tamaño de la foto', fr: 'Taille de la photo', ar: 'حجم الصورة', ru: 'Размер фото' },
  passportPreviewLabel: { en: 'Preview   {w} × {h} px @ 300 DPI', es: 'Vista previa: {w} × {h} px a 300 DPI', fr: 'Aperçu   {w} × {h} px à 300 DPI', ar: 'معاينة   {w} × {h} px بدقة 300 DPI', ru: 'Предпросмотр   {w} × {h} px при 300 DPI' },
  downloadPhoto: { en: 'Download photo', es: 'Descargar foto', fr: 'Télécharger la photo', ar: 'تنزيل الصورة', ru: 'Скачать фото' },
  printSheetCopies: { en: 'Print sheet ({count} copies)', es: 'Hoja de impresión ({count} copias)', fr: "Planche d'impression ({count} copies)", ar: 'ورقة الطباعة ({count} نسخ)', ru: 'Лист для печати ({count} копий)' },
  printSheetNote: { en: 'Print sheet: 4 × 6 in at 300 DPI, {count} copies with 3 mm gaps and light cut guides.', es: 'Hoja de impresión: 4 × 6 pulg. a 300 DPI, {count} copias con espacios de 3 mm y guías de corte claras.', fr: "Planche d'impression : 4 × 6 po à 300 DPI, {count} copies avec des espaces de 3 mm et des repères de coupe légers.", ar: 'ورقة الطباعة: 4 × 6 بوصة بدقة 300 DPI، {count} نسخ مع فواصل 3 mm وأدلة قص خفيفة.', ru: 'Лист для печати: 4 × 6 дюймов при 300 DPI, {count} копий с промежутками 3 мм и светлыми направляющими для резки.' },
  zoomWithValue: { en: 'Zoom   {value}×', es: 'Zoom: {value}×', fr: 'Zoom   {value}×', ar: 'التكبير   {value}×', ru: 'Масштаб   {value}×' },
  shiftHWithValue: { en: 'Shift left / right   {value}', es: 'Desplazar izquierda / derecha: {value}', fr: 'Décalage gauche / droite   {value}', ar: 'إزاحة يسار / يمين   {value}', ru: 'Сдвиг влево / вправо   {value}' },
  shiftVWithValue: { en: 'Shift up / down   {value}', es: 'Desplazar arriba / abajo: {value}', fr: 'Décalage haut / bas   {value}', ar: 'إزاحة أعلى / أسفل   {value}', ru: 'Сдвиг вверх / вниз   {value}' },
  passportTip: { en: 'Tip: your eyes should sit slightly above the middle of the frame and your head and shoulders should fill most of it.', es: 'Consejo: tus ojos deben quedar ligeramente por encima del centro del encuadre y tu cabeza y hombros deben llenar la mayor parte.', fr: 'Astuce : vos yeux doivent se situer légèrement au-dessus du milieu du cadre et votre tête et vos épaules doivent le remplir en grande partie.', ar: 'نصيحة: يجب أن تكون عيناك أعلى قليلاً من منتصف الإطار وأن يملأ رأسك وكتفاك معظم الإطار.', ru: 'Совет: ваши глаза должны быть немного выше середины кадра, а голова и плечи должны заполнять большую его часть.' },

  // ---- Favicon Generator ----
  faviconNote: { en: 'Square sources work best   images are center-cropped to a square. The .ico bundles 16, 32 and 48 px versions in one file, and the 180 px PNG is the Apple touch icon size.', es: 'Las fuentes cuadradas funcionan mejor: las imágenes se recortan al centro en un cuadrado. El archivo .ico incluye las versiones de 16, 32 y 48 px en un solo archivo, y el PNG de 180 px es el tamaño del icono táctil de Apple.', fr: "Les sources carrées fonctionnent le mieux   les images sont recadrées au centre en carré. Le fichier .ico regroupe les versions 16, 32 et 48 px dans un seul fichier, et le PNG de 180 px correspond à la taille de l'icône tactile Apple.", ar: 'تعمل المصادر المربعة بشكل أفضل   يتم قص الصور من المنتصف إلى مربع. يجمع ملف .ico إصدارات 16 و32 و48 px في ملف واحد، وحجم PNG البالغ 180 px هو حجم أيقونة اللمس من Apple.', ru: 'Лучше всего подходят квадратные исходники   изображения обрезаются по центру до квадрата. Файл .ico объединяет версии 16, 32 и 48 px в одном файле, а PNG 180 px   это размер сенсорной иконки Apple.' },
  chooseImageFirst: { en: 'Choose an image first.', es: 'Elige primero una imagen.', fr: "Choisissez d'abord une image.", ar: 'اختر صورة أولًا.', ru: 'Сначала выберите изображение.' },
  enterLetterFirst: { en: 'Enter a letter, initials or an emoji first.', es: 'Introduce primero una letra, iniciales o un emoji.', fr: "Saisissez d'abord une lettre, des initiales ou un emoji.", ar: 'أدخل حرفًا أو الأحرف الأولى أو رمزًا تعبيريًا أولًا.', ru: 'Сначала введите букву, инициалы или эмодзи.' },
  faviconFailed: { en: 'Favicon generation failed.', es: 'No se pudo generar el favicon.', fr: 'La génération du favicon a échoué.', ar: 'فشل إنشاء الأيقونة المفضلة.', ru: 'Не удалось сгенерировать favicon.' },
