  downloadAllZip: { en: 'Download all (ZIP)', es: 'Descargar todo (ZIP)', fr: 'Tout télécharger (ZIP)', ar: 'تنزيل الكل (ZIP)', ru: 'Скачать всё (ZIP)' },
