  addToYourSite: { en: 'Add to your site   paste into <head>', es: 'Añádelo a tu sitio: pégalo en <head>', fr: 'Ajoutez-le à votre site   collez dans <head>', ar: 'أضفه إلى موقعك   الصقه في <head>', ru: 'Добавьте на свой сайт   вставьте в <head>' },
