  // ---- Image Watermark ----
  watermarkNote: { en: "The preview is scaled down   downloads are rendered again at the photo's full resolution. A tiled, semi-transparent watermark is the hardest to remove; a corner mark is the least intrusive.", es: 'La vista previa está reducida: las descargas se generan de nuevo a la resolución completa de la foto. Una marca de agua en mosaico y semitransparente es la más difícil de eliminar; una marca en la esquina es la menos intrusiva.', fr: "L'aperçu est réduit   les téléchargements sont régénérés à la pleine résolution de la photo. Un filigrane en mosaïque semi-transparent est le plus difficile à supprimer ; une marque dans un coin est la moins intrusive.", ar: 'تم تصغير المعاينة   تتم إعادة تصيير التنزيلات بدقة الصورة الكاملة. العلامة المائية المبلطة وشبه الشفافة هي الأصعب في الإزالة؛ العلامة في الزاوية هي الأقل تدخلًا.', ru: 'Предпросмотр уменьшен   загрузки рендерятся заново в полном разрешении фотографии. Плиточный полупрозрачный водяной знак труднее всего удалить; знак в углу   наименее навязчивый.' },
  textWatermark: { en: 'Text watermark', es: 'Marca de agua de texto', fr: 'Filigrane texte', ar: 'علامة مائية نصية', ru: 'Текстовый водяной знак' },
  logoWatermark: { en: 'Logo watermark', es: 'Marca de agua con logo', fr: 'Filigrane logo', ar: 'علامة مائية بشعار', ru: 'Водяной знак-логотип' },
  watermarkText: { en: 'Watermark text', es: 'Texto de la marca de agua', fr: 'Texte du filigrane', ar: 'نص العلامة المائية', ru: 'Текст водяного знака' },
  textSizePctOfWidth: { en: 'Text size   {value}% of width', es: 'Tamaño del texto: {value}% del ancho', fr: 'Taille du texte   {value} % de la largeur', ar: 'حجم النص   {value}% من العرض', ru: 'Размер текста   {value}% ширины' },
  opacityLabel: { en: 'Opacity   {value}%', es: 'Opacidad: {value}%', fr: 'Opacité   {value} %', ar: 'العتامة   {value}%', ru: 'Непрозрачность   {value}%' },
