  logoSizePctOfWidth: { en: 'Logo size   {value}% of image width', es: 'Tamaño del logo: {value}% del ancho de la imagen', fr: "Taille du logo   {value} % de la largeur de l'image", ar: 'حجم الشعار   {value}% من عرض الصورة', ru: 'Размер логотипа   {value}% ширины изображения' },
