  maxImagesReached: { en: 'Maximum of 9 images reached.', es: 'Se alcanzó el máximo de 9 imágenes.', fr: 'Maximum de 9 images atteint.', ar: 'تم الوصول إلى الحد الأقصى وهو 9 صور.', ru: 'Достигнут максимум из 9 изображений.' },
