  downloadTilesZip: { en: 'Download tiles ZIP', es: 'Descargar mosaicos ZIP', fr: 'Télécharger le ZIP des tuiles', ar: 'تنزيل البلاطات ZIP', ru: 'Скачать плитки ZIP' },
